  --code-padding-x: 1.25rem;
  --code-padding-y: 1rem;
  --code-border-radius: 6px;
  --code-line-height: 1.6;
  --code-font-size: .875em;
  --code-font-family: consolas, monaco, "Andale Mono", "Ubuntu Mono", monospace;
}

div[class*="language-"] {
  border-radius: var(--code-border-radius);
  background-color: var(--code-c-bg);
  transition: background-color var(--vp-t-color), color var(--vp-t-color);
  margin-block: .75rem;
  position: relative;
}

div[class*="language-"]:before {
  content: attr(data-ext);
  z-index: 3;
  color: var(--code-c-text);
  font-size: .75rem;
  position: absolute;
  top: .8em;
  right: 1em;
}

div[class*="language-"] pre {
  z-index: 1;
  border-radius: var(--code-border-radius);
  font-size: var(--code-font-size);
  font-family: var(--code-font-family);
  line-height: var(--code-line-height);
  margin: 0;
  position: relative;
  overflow-x: auto;
}

div[class*="language-"] pre code {
  box-sizing: border-box;
  width: -moz-fit-content;
  width: fit-content;
  min-width: 100%;
  padding: var(--code-padding-y) var(--code-padding-x);
  color: var(--code-c-text);
  overflow-wrap: unset;
  -webkit-font-smoothing: auto;
  -moz-osx-font-smoothing: auto;
  display: block;
  background-color: #0000 !important;
}

@media print {
  div[class*="language-"] pre code {
    white-space: pre-wrap;
  }
}
