___CSS_LOADER_EXPORT___.push([module.id, `.vp-back-to-top-button {
  inset-inline-end: 1rem;
  z-index: 100;
  background: var(--back-to-top-c-bg);
  width: 48px;
  height: 48px;
  color: var(--back-to-top-c-accent-bg);
  box-shadow: 2px 2px 10px 4px var(--back-to-top-c-shadow);
  cursor: pointer;
  border-width: 0;
  border-radius: 50%;
  padding: 12px;
  bottom: 4rem;
  position: fixed !important;
}

@media (max-width: 959px) {
  .vp-back-to-top-button {
    transform-origin: 100% 100%;
    transform: scale(.8);
  }
}

@media print {
  .vp-back-to-top-button {
    display: none;
  }
}

.vp-back-to-top-button:hover {
  color: var(--back-to-top-c-accent-hover);
}

.vp-back-to-top-button .back-to-top-icon {
  background: var(--back-to-top-c-icon);
  width: 24px;
  height: 24px;
  -webkit-mask-image: var(--back-to-top-icon);
  mask-image: var(--back-to-top-icon);
  margin: 0 auto;
  overflow: hidden;
  -webkit-mask-position: 50%;
  mask-position: 50%;
  -webkit-mask-size: cover;
  mask-size: cover;
}

.vp-scroll-progress {
  inset-inline-end: -2px;
  width: 52px;
  height: 52px;
  position: absolute;
  bottom: -2px;
}

.vp-scroll-progress svg {
  width: 100%;
  height: 100%;
}

.vp-scroll-progress circle {
  opacity: .9;
  transform-origin: 50%;
  transform: rotate(-90deg);
}
