.vp-changelog-wrapper {
  background-color: var(--changelog-bg);
  color: var(--changelog-c-text);
  font-size: var(--changelog-font-size);
  transition: background-color var(--vp-t-color);
  border-radius: 8px;
  margin-block: 1rem;
  padding-inline: 1rem;
  line-height: 1.7;
}

.vp-changelog-wrapper.active {
  padding-block: 0 .5rem;
}

.vp-changelog-wrapper a {
  text-decoration: none !important;
}

.vp-changelog-wrapper a:after {
  display: none !important;
}

.vp-changelog-header {
  cursor: pointer;
  justify-content: space-between;
  align-items: center;
  padding-block: 1rem;
  font-weight: bold;
  display: flex;
}

@media (max-width: 419px) {
  .vp-changelog-header {
    flex-wrap: wrap;
  }
}

.vp-changelog-wrapper.active .vp-changelog-header {
  padding-block-end: .5rem;
}

.vp-changelog-icon, .vp-changelog-menu-icon {
  vertical-align: middle;
  width: 1.2em;
  height: 1.2em;
  color: var(--vp-c-text-mute);
  -webkit-mask: var(--icon) no-repeat;
  mask: var(--icon) no-repeat;
  transition: color var(--vp-t-color);
  background-color: currentColor;
  margin-inline-end: 4px;
  display: inline-block;
  transform: translateY(-1px);
  -webkit-mask-size: 100% 100%;
  mask-size: 100% 100%;
}

.vp-changelog-icon {
  --icon: url(${___CSS_LOADER_URL_REPLACEMENT_0___});
}

.vp-changelog-menu-icon {
  --icon: url(${___CSS_LOADER_URL_REPLACEMENT_1___});
}

